--
-- Table structure for table `manuals`
--

DROP TABLE IF EXISTS `manuals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `manuals` (
  `manual_id` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `device_category` enum('Air Conditioner','Microwave','Refrigerator','Television','Washing Machine') COLLATE utf8mb4_unicode_ci NOT NULL,
  `brand` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `model_pattern` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_manual` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ชื่อไฟล์คู่มือต้นฉบับ ใช้สร้างการอ้างอิง',
  `graph_count` smallint unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `display_name` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ชื่อรุ่นที่ผู้ใช้รู้จัก เติมโดยผู้พัฒนาจากคู่มือ NULL = แสดง model_pattern แทน',
  `model_aliases` json DEFAULT NULL COMMENT 'เลขรุ่น/ชื่อขายอื่นที่ใช้คู่มือเล่มนี้ (อาร์เรย์ของข้อความ) NULL = ไม่มี',
  PRIMARY KEY (`manual_id`),
  KEY `idx_manuals_category` (`device_category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

