--
-- Table structure for table `nodes`
--

DROP TABLE IF EXISTS `nodes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `nodes` (
  `graph_id` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `node_id` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `node_type` enum('checkpoint','instruction','input','resolution','escalation') COLLATE utf8mb4_unicode_ci NOT NULL,
  `text_content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'question / content / prompt แล้วแต่ node_type',
  `on_yes` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'checkpoint เท่านั้น',
  `on_no` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'checkpoint เท่านั้น',
  `next_node` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'instruction และ input',
  `on_invalid` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'input เท่านั้น ถ้า NULL = วนกลับโหนดเดิม',
  `input_type` enum('error_code','model_number','number','text') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `input_pattern` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'regex ที่คำตอบต้องผ่าน',
  `store_as` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'key ที่เก็บค่าลง session.variables',
  `outcome_kind` enum('user_fixed','normal_behavior','handoff_informed','handoff_unknown') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `safety_critical` tinyint(1) NOT NULL DEFAULT '0',
  `safety_warning` text COLLATE utf8mb4_unicode_ci,
  `has_image` tinyint(1) NOT NULL DEFAULT '0',
  `image_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `author_note` text COLLATE utf8mb4_unicode_ci COMMENT 'ระบุข้อความที่ผู้พัฒนาเพิ่มเอง ไม่ได้มาจากคู่มือ',
  `external_reference` json DEFAULT NULL,
  `display_order` smallint unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`graph_id`,`node_id`),
  KEY `idx_nodes_type` (`node_type`),
  KEY `idx_nodes_safety` (`safety_critical`),
  CONSTRAINT `fk_nodes_graph` FOREIGN KEY (`graph_id`) REFERENCES `graphs` (`graph_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

