/*!40000 ALTER TABLE `nodes` DISABLE KEYS */;
INSERT INTO `nodes` VALUES ('samsung_ac_ar70h_cannot_change_airflow_direction','n_check_after_disable','checkpoint','หลังปิดฟังก์ชัน Good Sleep แล้ว ปรับทิศทางลมได้หรือไม่?','n_resolved','n_escalate',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,2,'2026-10-16 02:41:37'),('samsung_ac_ar70h_cannot_change_airflow_direction','n_escalate','escalation','คู่มือระบุสาเหตุเดียวสำหรับอาการนี้คือฟังก์ชัน Good Sleep ในโหมด Cool หากไม่ใช่กรณีนี้ บานปรับทิศทางลมอาจติดขัดหรือมอเตอร์มีปัญหา แนะนำให้ติดต่อศูนย์บริการ Samsung',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'handoff_unknown',0,NULL,0,NULL,NULL,NULL,4,'2026-10-16 02:41:37'),('samsung_ac_ar70h_cannot_change_airflow_direction','n_explain_good_sleep','instruction','เมื่อเปิดฟังก์ชัน Good Sleep ในโหมด Cool เครื่องจะล็อกทิศทางลมไว้อัตโนมัติ ผู้ใช้ไม่สามารถปรับเองได้ หากต้องการปรับทิศทางลม ให้ปิดฟังก์ชัน Good Sleep ก่อน',NULL,NULL,'n_check_after_disable',NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,1,'2026-10-16 02:41:37'),('samsung_ac_ar70h_cannot_change_airflow_direction','n_resolved','resolution','ปรับทิศทางลมได้แล้ว — สาเหตุคือฟังก์ชัน Good Sleep ล็อกทิศทางลมไว้ ซึ่งเป็นการทำงานปกติของเครื่อง',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'normal_behavior',0,NULL,0,NULL,NULL,NULL,3,'2026-10-16 02:41:37'),('samsung_ac_ar70h_cannot_change_airflow_direction','n1','checkpoint','ฟังก์ชัน Good Sleep เปิดใช้งานอยู่ในโหมด Cool หรือไม่?','n_explain_good_sleep','n_escalate',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,0,'2026-10-16 02:41:37'),('samsung_ac_ar70h_cannot_change_fan_speed','n_check_after_mode','checkpoint','หลังเปลี่ยนโหมดหรือปิดฟังก์ชันแล้ว ปรับความเร็วพัดลมได้หรือไม่?','n_resolved','n_escalate',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,4,'2026-10-16 02:41:40'),('samsung_ac_ar70h_cannot_change_fan_speed','n_escalate','escalation','อาการไม่ตรงกับสาเหตุที่ระบุไว้ในคู่มือ (โหมด AI Auto, โหมด Dry, หรือฟังก์ชัน Good Sleep) แนะนำให้ติดต่อศูนย์บริการ Samsung พร้อมแจ้งรุ่นเครื่องและโหมดที่ใช้งานอยู่',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'handoff_unknown',0,NULL,0,NULL,NULL,NULL,6,'2026-10-16 02:41:40'),('samsung_ac_ar70h_cannot_change_fan_speed','n_explain_auto_dry','instruction','ในโหมด AI Auto และโหมด Dry เครื่องจะควบคุมความเร็วพัดลมอัตโนมัติ ผู้ใช้ไม่สามารถปรับเองได้ หากต้องการปรับความเร็วพัดลม ให้เปลี่ยนไปใช้โหมด Cool หรือ Fan ด้วยปุ่ม Mode บนรีโมท',NULL,NULL,'n_check_after_mode',NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,1,'2026-10-16 02:41:40'),('samsung_ac_ar70h_cannot_change_fan_speed','n_explain_good_sleep','instruction','เมื่อเปิดฟังก์ชัน Good Sleep ในโหมด Cool เครื่องจะควบคุมความเร็วพัดลมอัตโนมัติเพื่อให้เหมาะกับการนอน ผู้ใช้ไม่สามารถปรับเองได้ หากต้องการปรับ ให้ปิดฟังก์ชัน Good Sleep ก่อน',NULL,NULL,'n_check_after_mode',NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,3,'2026-10-16 02:41:40'),('samsung_ac_ar70h_cannot_change_fan_speed','n_resolved','resolution','ปรับความเร็วพัดลมได้แล้ว — สาเหตุคือเครื่องอยู่ในโหมดที่ควบคุมความเร็วพัดลมอัตโนมัติ ซึ่งเป็นการทำงานปกติของเครื่อง',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'normal_behavior',0,NULL,0,NULL,NULL,NULL,5,'2026-10-16 02:41:40'),('samsung_ac_ar70h_cannot_change_fan_speed','n1','checkpoint','เครื่องอยู่ในโหมด AI Auto หรือโหมด Dry อยู่หรือไม่? ดูที่หน้าจอเครื่องภายในหรือรีโมท','n_explain_auto_dry','n2',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,0,'2026-10-16 02:41:40'),('samsung_ac_ar70h_cannot_change_fan_speed','n2','checkpoint','ฟังก์ชัน Good Sleep เปิดใช้งานอยู่ในโหมด Cool หรือไม่?','n_explain_good_sleep','n_escalate',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,2,'2026-10-16 02:41:40'),('samsung_ac_ar70h_cannot_change_temperature','n_confirm_mode_change','checkpoint','หลังเปลี่ยนเป็นโหมด Cool แล้ว ตั้งอุณหภูมิได้หรือไม่?','n_resolved','n_escalate',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,2,'2026-10-16 02:41:40'),('samsung_ac_ar70h_cannot_change_temperature','n_escalate','escalation','อาการไม่ตรงกับสาเหตุที่ระบุไว้ในคู่มือ (โหมด Fan) แนะนำให้ติดต่อศูนย์บริการ Samsung พร้อมแจ้งรุ่นเครื่องและอาการที่พบ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'handoff_unknown',0,NULL,0,NULL,NULL,NULL,4,'2026-10-16 02:41:40'),('samsung_ac_ar70h_cannot_change_temperature','n_explain_fan_mode','instruction','ในโหมด Fan เครื่องจะไม่สามารถตั้งอุณหภูมิได้ เพราะโหมดนี้ทำหน้าที่หมุนเวียนอากาศเท่านั้น ไม่ได้ทำความเย็น หากต้องการตั้งอุณหภูมิ ให้เปลี่ยนไปใช้โหมด Cool ด้วยปุ่ม Mode บนรีโมทคอนโทรล',NULL,NULL,'n_confirm_mode_change',NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,1,'2026-10-16 02:41:40'),('samsung_ac_ar70h_cannot_change_temperature','n_resolved','resolution','แก้ไขเรียบร้อย — สาเหตุคือเครื่องอยู่ในโหมด Fan ซึ่งไม่รองรับการตั้งอุณหภูมิ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'normal_behavior',0,NULL,0,NULL,NULL,NULL,3,'2026-10-16 02:41:40'),('samsung_ac_ar70h_cannot_change_temperature','n1','checkpoint','เครื่องกำลังทำงานอยู่ในโหมด Fan (พัดลม) หรือไม่? ดูที่หน้าจอเครื่องในหรือรีโมท','n_explain_fan_mode','n_escalate',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,0,'2026-10-16 02:41:40'),('samsung_ac_ar70h_condensation_indoor','n_escalate','escalation','อาการควบแน่นที่เกิดขึ้นนอกเงื่อนไขที่คู่มือระบุ อาจเกี่ยวข้องกับฉนวนท่อเสื่อมสภาพหรือปริมาณสารทำความเย็นผิดปกติ แนะนำให้ติดต่อศูนย์บริการ Samsung เพื่อตรวจสอบ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'handoff_unknown',0,NULL,0,NULL,NULL,NULL,4,'2026-10-16 02:41:41'),('samsung_ac_ar70h_condensation_indoor','n_escalate_leak','escalation','น้ำที่ไหลหยดลงพื้นเป็นทางไม่ใช่อาการควบแน่นปกติ อาจเกิดจากท่อน้ำทิ้งอุดตัน ถาดรองน้ำแตกร้าว หรือการติดตั้งไม่ได้ระดับ แนะนำให้ปิดเครื่องและติดต่อศูนย์บริการ Samsung เพื่อป้องกันความเสียหายต่อฝ้าเพดานหรือผนัง',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'handoff_informed',0,NULL,0,NULL,NULL,NULL,3,'2026-10-16 02:41:41'),('samsung_ac_ar70h_condensation_indoor','n_normal','resolution','นี่เป็นอาการปกติ ไม่ใช่ความเสียหาย — เมื่อความชื้นในห้องสูงหรืออุณหภูมิที่ตั้งไว้ต่างจากอุณหภูมิห้องมาก ไอน้ำในอากาศจะควบแน่นเป็นหยดน้ำบนผิวเครื่องที่เย็น หากต้องการลดอาการนี้ ให้ปรับอุณหภูมิให้สูงขึ้นเล็กน้อย ห