INSERT INTO `nodes` VALUES ('samsung_wa21a_um_does_not_turn_on','n3f','instruction','ตรวจฟิวส์หรือรีเซ็ตเบรกเกอร์ (คู่มือหน้า 38)',NULL,NULL,'n3v',NULL,NULL,NULL,NULL,NULL,1,'ห้ามใช้ฟิวส์ที่ไม่ใช่ฟิวส์มาตรฐาน (เช่น ลวดทองแดงหรือลวดเหล็ก) และห้ามซ่อมหรือดัดแปลงเครื่องเอง ถ้าเบรกเกอร์ตัดซ้ำหลังรีเซ็ต ให้หยุดใช้งานและติดต่อศูนย์บริการ (คู่มือหน้า 7)',0,NULL,'คู่มือหน้า 38 ระบุเพียง \'Check the fuse or reset the circuit breaker\' ส่วนคำเตือนเรื่องฟิวส์มาตรฐานมาจากหน้า 7 และประโยค \'ถ้าเบรกเกอร์ตัดซ้ำให้หยุดใช้งาน\' ผู้พัฒนาเพิ่มเอง',NULL,7,'2026-10-16 02:59:42'),('samsung_wa21a_um_does_not_turn_on','n3v','checkpoint','หลังทำตามแล้ว อาการหายหรือไม่? (ให้เวลาตามสมควร)','n_resolved','n_escalate',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,'ระยะเวลาสังเกตผลไม่ระบุในคู่มือ',NULL,8,'2026-10-16 02:59:42'),('samsung_wa21a_um_door_locked','n_escalate','escalation','ทำตามรายการตรวจแล้วฝายังเปิดไม่ได้ ห้ามฝืนเปิดฝาด้วยแรง (คู่มือหน้า 29) ติดต่อศูนย์บริการ Samsung ในพื้นที่ พร้อมแจ้งรุ่นเครื่องและสิ่งที่ได้ตรวจไปแล้ว',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'handoff_unknown',0,NULL,0,NULL,NULL,NULL,7,'2026-10-16 02:59:45'),('samsung_wa21a_um_door_locked','n_resolved','resolution','เปิดฝาเครื่องได้แล้ว',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'user_fixed',0,NULL,0,NULL,NULL,NULL,6,'2026-10-16 02:59:45'),('samsung_wa21a_um_door_locked','n1','checkpoint','Child Lock เปิดใช้งานอยู่ใช่หรือไม่?','n1f','n2',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,0,'2026-10-16 02:59:45'),('samsung_wa21a_um_door_locked','n1f','instruction','ปลดล็อกเด็ก (Child Lock) โดยกดปุ่ม Water Level และ Wash Time ค้างพร้อมกันประมาณ 3 วินาที ไฟ Child Lock จะดับ (คู่มือหน้า 29)',NULL,NULL,'n1v',NULL,NULL,NULL,NULL,NULL,1,'ฟังก์ชัน Child Lock ล็อกฝาเครื่องเพื่อป้องกันเด็กปีนเข้าไปในถัง ห้ามฝืนเปิดฝาด้วยแรง เพราะอาจบาดเจ็บหรือเครื่องเสียหาย (คู่มือหน้า 28 และ 29)',0,NULL,'หน้า 40 ไม่ได้พูดถึง Child Lock ผู้พัฒนาเพิ่มจากหน้า 28 และ 29 ซึ่งระบุว่า Child Lock ล็อกฝาเครื่อง และต้องปลดก่อนเติมผ้า',NULL,1,'2026-10-16 02:59:45'),('samsung_wa21a_um_door_locked','n1v','checkpoint','หลังทำตามแล้ว เปิดฝาเครื่องได้หรือไม่?','n_resolved','n2',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,2,'2026-10-16 02:59:45'),('samsung_wa21a_um_door_locked','n2','checkpoint','เครื่องกำลังทำงานอยู่ใช่หรือไม่?','n2f','n_escalate',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,3,'2026-10-16 02:59:45'),('samsung_wa21a_um_door_locked','n2f','instruction','กดปุ่ม Hold to Start เพื่อหยุดเครื่อง แล้วรอสักครู่ให้กลไกล็อกฝาปลดออก (คู่มือหน้า 40)',NULL,NULL,'n2v',NULL,NULL,NULL,NULL,NULL,1,'ห้ามยื่นมือเข้าไปในถังขณะถังกำลังหมุนปั่นแห้ง ถ้าถังไม่หยุดหมุนภายใน 15 วินาทีหลังเปิดฝา ให้ติดต่อศูนย์บริการ Samsung และห้ามฝืนเปิดฝาด้วยแรง (คู่มือหน้า 7 และ 29)',0,NULL,'หน้า 40 ระบุว่าอาจใช้เวลาสักครู่แต่ไม่ระบุระยะเวลา คำเตือนเรื่องไม่ฝืนเปิดฝาและมือในถังที่หมุนมาจากหน้า 7 และ 29',NULL,4,'2026-10-16 02:59:45'),('samsung_wa21a_um_door_locked','n2v','checkpoint','หลังทำตามแล้ว เปิดฝาเครื่องได้หรือไม่?','n_resolved','n_escalate',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,'ระยะเวลาสังเกตผลไม่ระบุในคู่มือ',NULL,5,'2026-10-16 02:59:45'),('samsung_wa21a_um_excessive_suds','n_escalate','escalation','ไม่พบสาเหตุที่ตรงกับรายการตรวจในคู่มือ ติดต่อศูนย์บริการ Samsung ในพื้นที่ พร้อมแจ้งรุ่นเครื่อง อาการ และสิ่งที่ได้ตรวจไปแล้ว',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'handoff_unknown',0,NULL,0,NULL,NULL,NULL,7,'2026-10-16 02:59:46'),('samsung_wa21a_um_excessive_suds','n_resolved','resolution','ฟองลดลงแล้ว',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'user_fixed',0,NULL,0,NULL,NULL,NULL,6,'2026-10-16 02:59:46'),('samsung_wa21a_um_excessive_suds','n1','checkpoint','ใช้ผงซักฟอกประสิทธิภาพสูง (HE) หรือไม่?','n2','n1f',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,0,'2026-10-16 02:59:46'),('samsung_wa21a_um_excessive_suds','n1f','instruction','ใช้ผงซักฟอก HE เพื่อป้องกันฟองมากเกินไป คู่มือไม่แนะนำผงซักฟอกที่ไม่ใช่ HE (คู่มือหน้า 41)',NULL,NULL,'n1v',NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,1,'2026-10-16 02:59:46'),('samsung_wa21a_um_excessive_suds','n1v','checkpoint','หลังทำตามแล้ว อาการหายหรือไม่?','n_resolved','n2',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,2,'2026-10-16 02:59:46'),('samsung_wa21a_um_excessive_suds','n2','checkpoint','ลดปริมาณผงซักฟอกแล้วหรือไม่ เมื่อใช้น้ำอ่อน ซักผ้าน้อย หรือผ้าไม่สกปรกมาก?','n_escalate','n2f',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,3,'2026-10-16 02:59:46'),('samsung_wa21a_um_excessive_suds','n2f','instruction','ลดปริมาณผงซักฟอกลงสำหรับน้ำอ่อน ผ้าน้อย หรือผ้าไม่สกปรกมาก (คู่มือหน้า 41)',NULL,NULL,'n2v',NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,4,'2026-10-16 02:59:46'),('samsung_wa21a_um_excessive_suds','n2v','checkpoint','หลังทำตามแล้ว อาการหายหรือไม่?','n_resolved','n_escalate',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,5,'2026-10-16 02:59:46'),('samsung_wa21a_um_frozen','n_escalate','escalation','ทำตามขั้นตอนแก้ปัญหาสายแข็งตัวแล้วเครื่องยังไม่ทำงานปกติ ติดต่อศูนย์บริการ Samsung ในพื้นที่ พร้อมแจ้งรุ่นเครื่องและสิ่งที่ได้ทำไปแล้ว',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'handoff_unknown',0,NULL,0,NULL,NULL,NULL,7,'2026-10-16 02:59:46'),('samsung_wa21a_um_frozen','n_nomatch','escalation','อาการไม่ตรงกับกรณีที่คู่มือระบุ (ถังซักหรือสายแข็งตัว) ติดต่อศูนย์บริการ Samsung พร้อมแจ้งรุ่นเครื่องและอาการที่พบ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'handoff_unknown',0,NULL,0,NULL,NULL,NULL,8,'2026-10-16 02:59:46'),('samsung_wa21a_um_frozen','n_resolved','resolution','เครื่องกลับมาทำงานปกติแล้ว',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'user_fixed',0,NULL,0,NULL,NULL,NULL,6,'2026-10-16 02:59:46'),('samsung_wa21a_um_frozen','n1','checkpoint','อุณหภูมิต่ำจนคุณสงสัยว่าถังซัก สายน้ำเข้า หรือสายระบายน้ำแข็งตัวใช่หรือไม่?','n2','n_nomatch',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,0,'2026-10-16 02:59:46'),('samsung_wa21a_um_frozen','n2','instruction','ถอดปลั๊ก แล้วใช้น้ำอุ่นถอดสายน้ำเข้าและสายระบายน้ำ แช่สายทั้งสองในน้ำอุ่น (คู่มือหน้า 41)',NULL,NULL,'n3',NULL,NULL,NULL,NULL,NULL,1,'ห้ามใช้น้ำร้อนเกิน 50 °C เพราะชิ้นส่วนพลาส