--
-- Table structure for table `sessions`
--

DROP TABLE IF EXISTS `sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sessions` (
  `session_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `graph_id` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `current_node_id` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('in_progress','completed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'in_progress',
  `variables` json NOT NULL,
  `confidence` decimal(4,3) DEFAULT NULL COMMENT 'คะแนนความคล้าย (cosine) ของผังที่เลือก NULL = ไม่มีการจับคู่ให้วัด',
  `outcome_text` text COLLATE utf8mb4_unicode_ci COMMENT 'ข้อความผลลัพธ์ที่ผู้ใช้กรอกตอนการตรวจจบ NULL = ยังไม่ได้กรอก (บันทึกอย่างเดียว ไม่มีผลต่อการเปลี่ยนสถานะ)',
  `outcome_at` datetime DEFAULT NULL COMMENT 'เวลาที่บันทึก outcome_text (NOW() ใน SQL) NULL = ยังไม่ได้กรอก',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `expires_at` timestamp NOT NULL,
  `model_selection` enum('selected','unknown') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'selected = เลือกรุ่นเอง · unknown = ไม่ทราบรุ่นแล้วเลือกใกล้เคียง · NULL = ไม่ได้ผ่านหน้าเลือกรุ่น',
  `client_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'UUID ของเบราว์เซอร์เจ้าของ (หน้าประวัติการซ่อม) · NULL = ไม่ทราบเจ้าของ',
  `user_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'users.id ของเจ้าของที่ล็อกอิน · NULL = guest (ดู client_id) หรือ session เก่า',
  PRIMARY KEY (`session_id`),
  KEY `fk_sessions_graph` (`graph_id`),
  KEY `idx_sessions_expires` (`expires_at`),
  KEY `idx_sessions_status` (`status`),
  KEY `idx_sessions_client` (`client_id`,`status`,`expires_at`),
  KEY `idx_sessions_user` (`user_id`,`status`,`expires_at`),
  CONSTRAINT `fk_sessions_graph` FOREIGN KEY (`graph_id`) REFERENCES `graphs` (`graph_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_sessions_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

